def split(xs: List[int]) -> Tuple[List[int], List[int]]:
    mid = len(xs) // 2
    return xs[:mid], xs[mid:]


def merge(xs: List[int], ys: List[int]) -> List[int]:
    result = []
    i = 0
    j = 0
    while i < len(xs) and j < len(ys):
        if xs[i] < ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1
    result.extend(xs[i:])
    result.extend(ys[j:])
    return result


def mergeSort(xs: List[int]) -> List[int]:
    if len(xs) <= 1:
        return xs
    left, right = split(xs)
    return merge(mergeSort(left), mergeSort(right))


