from dataclasses import dataclass
from typing import Union

# State variants
@dataclass
class Idle:
    pass

@dataclass
class HasCredit:
    cents: int

@dataclass
class Dispensing:
    change: int

State = Union[Idle, HasCredit, Dispensing]

# Event variants
@dataclass
class Insert:
    cents: int

@dataclass
class Select:
    code: int

@dataclass
class DispenseDone:
    pass

Event = Union[Insert, Select, DispenseDone]

# Result variants
@dataclass
class Ok:
    state: State

@dataclass
class Err:
    reason: str

Result = Union[Ok, Err]

# Item prices
PRICES = {
    1: 125,  # cola
    2: 75,   # chips
    3: 100,  # water
}

def step(state: State, event: Event) -> Result:
    """
    State transition function.
    Returns Ok(newState) or Err(reason).
    """
    match (state, event):
        # Idle state
        case (Idle(), Insert(cents)):
            return Ok(HasCredit(cents))
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        # HasCredit state
        case (HasCredit(credit), Insert(cents)):
            return Ok(HasCredit(credit + cents))
        case (HasCredit(credit), Select(code)):
            if code not in PRICES:
                return Err("unknown_item")
            price = PRICES[code]
            if credit < price:
                return Err("insufficient_funds")
            change = credit - price
            return Ok(Dispensing(change))
        case (HasCredit(_), DispenseDone()):
            return Err("not_dispensing")

        # Dispensing state
        case (Dispensing(_), Insert(_)):
            return Err("busy")
        case (Dispensing(_), Select(_)):
            return Err("busy")
        case (Dispensing(change), DispenseDone()):
            if change > 0:
                return Ok(HasCredit(change))
            else:
                return Ok(Idle())

def format_state(state: State) -> str:
    """Format state for output."""
    match state:
        case Idle():
            return "IDLE"
        case HasCredit(cents):
            return f"CREDIT({cents})"
        case Dispensing(change):
            return f"DISPENSING({change})"

def main():
    state: State = Idle()

    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    for event in events:
        result = step(state, event)
        match result:
            case Ok(new_state):
                print(f"ok: {format_state(new_state)}")
                state = new_state
            case Err(reason):
                print(f"err: {reason}")

if __name__ == "__main__":
    main()

from typing import Callable, List, Union

class Tree:
    pass

class Leaf(Tree):
    def __init__(self, value: int):
        self.value = value

class Node(Tree):
    def __init__(self, left: Tree, value: int, right: Tree):
        self.left = left
        self.value = value
        self.right = right

def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            map_tree(fn, tree.left),
            fn(tree.value),
            map_tree(fn, tree.right)
        )
    raise TypeError("Invalid tree node")

def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        acc = fold_tree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        return fold_tree(fn, acc, tree.right)
    raise TypeError("Invalid tree node")

def tree_to_list(tree: Tree) -> List[int]:
    if isinstance(tree, Leaf):
        return [tree.value]
    elif isinstance(tree, Node):
        return tree_to_list(tree.left) + [tree.value] + tree_to_list(tree.right)
    raise TypeError("Invalid tree node")

def get_tree_depth(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(get_tree_depth(tree.left), get_tree_depth(tree.right))
    raise TypeError("Invalid tree node")

def main():
    example_tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # In-order values: [1, 2, 3, 4, 5, 6, 7]
    print(tree_to_list(example_tree))

    # Doubled values: [2, 4, 6, 8, 10, 12, 14]
    doubled_tree = map_tree(lambda x: x * 2, example_tree)
    print(tree_to_list(doubled_tree))

    # Sum of all values: 28
    total_sum = fold_tree(lambda acc, x: acc + x, 0, example_tree)
    print(total_sum)

    # Tree depth: 3
    print(get_tree_depth(example_tree))

if __name__ == "__main__":
    main()

