from __future__ import annotations
from dataclasses import dataclass
from typing import List, Tuple, Union

@dataclass
class Type:
    pass

@dataclass
class TVar(Type):
    name: str

@dataclass
class TInt(Type):
    pass

@dataclass
class TBool(Type):
    pass

@dataclass
class TFunc(Type):
    arg: Type
    result: Type

Subst = List[Tuple[str, Type]]

def apply(subst: Subst, t: Type) -> Type:
    if isinstance(t, TVar):
        for var, typ in subst:
            if var == t.name:
                return typ
        return t
    if isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    return t

def unify(t1: Type, t2: Type) -> Subst:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        r1 = apply(s1, t1.result)
        r2 = apply(s1, t2.result)
        s2 = unify(r1, r2)
        return s1 + s2
    raise ValueError("Unification failed")

def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    s = unify(t1, t2)
    for var, typ in s:
        if isinstance(typ, TBool):
            print(f"{var} = TBool")
        elif isinstance(typ, TInt):
            print(f"{var} = TInt")

if __name__ == "__main__":
    main()
